require dirname(__DIR__).'/bootstrap.php';method(['GET','POST']);$action=$_SERVER['REQUEST_METHOD']==='POST'?input('action','draw'):($_GET['action']??'config');$u=current_user();native_core((int)($u['uid']??0));global $_G,$pdo;
$config=one('SELECT max_draws,announcement FROM '.table('lottery_config').' WHERE id=1');$max=max(1,(int)($config['max_draws']??1));$start=strtotime('today');$end=strtotime('tomorrow');$prizes=rows('SELECT id,prize_name,credit_value,credit_type FROM '.table('lottery_prizes').' WHERE status=1 ORDER BY sort_order,id');
$count=$u?(int)one('SELECT COUNT(*) n FROM '.table('lottery_records').' WHERE uid=? AND dateline>=? AND dateline<?',[$u['uid'],$start,$end])['n']:0;
$status=['loggedIn'=>(bool)$u,'user'=>$u?user_public($u['uid']):null,'remaining'=>$u?max(0,$max-$count):0,'max_draws'=>$max,'reached'=>!$u||$count>=$max];
if($_SERVER['REQUEST_METHOD']==='GET'){
 if(!in_array($action,['config','check','prizes','drawcount'],true))respond(null,422,'抽奖操作无效');
 respond($status+['enabled'=>(bool)$prizes,'announcement_html'=>clean_html($config['announcement']??''),'prizes'=>array_map(function($p){return ['id'=>(int)$p['id'],'name'=>$p['prize_name'],'credit_value'=>(int)$p['credit_value']];},$prizes),'history'=>$u?rows('SELECT id,prize,dateline FROM '.table('lottery_records').' WHERE uid=? ORDER BY id DESC LIMIT 30',[$u['uid']]):[]]);
}
if($action!=='draw')respond(null,422,'抽奖操作无效');$u=current_user(true);$request=!empty($app_lottery_legacy)&&!input('request_id')?bin2hex(random_bytes(16)):text_input('request_id',64);if(!preg_match('/^[a-zA-Z0-9_-]{16,64}$/D',$request))respond(null,422,'抽奖请求标识无效');lock_user('lottery',$u['uid']);
$pdo->exec('CREATE TABLE IF NOT EXISTS '.table('app_lottery_request').' (uid MEDIUMINT UNSIGNED NOT NULL,request_id VARCHAR(64) NOT NULL,result TEXT NOT NULL,created INT UNSIGNED NOT NULL,PRIMARY KEY(uid,request_id)) ENGINE=InnoDB');
$old=one('SELECT result FROM '.table('app_lottery_request').' WHERE uid=? AND request_id=?',[$u['uid'],$request]);if($old)respond(json_decode($old['result'],true));rate('lottery:'.$u['uid'],5,60);
$count=(int)one('SELECT COUNT(*) n FROM '.table('lottery_records').' WHERE uid=? AND dateline>=? AND dateline<?',[$u['uid'],$start,$end])['n'];if($count>=$max)respond(null,403,'今日次数已用完，明天再来');
$pool=rows('SELECT * FROM '.table('lottery_prizes').' WHERE status=1 ORDER BY sort_order,id');if(!$pool)respond(null,403,'活动暂未开始');$random=random_int(1,1000000);$acc=0;$selected=['prize_name'=>'谢谢参与','credit_value'=>0,'credit_type'=>''];foreach($pool as $p){$acc+=(int)(max(0,(float)$p['probability'])*10000);if($random<=$acc){$selected=$p;break;}}
$credit=max(0,(int)$selected['credit_value']);$field=$selected['credit_type']?:'extcredits1';$title='';if(!preg_match('/^extcredits([1-8])$/D',$field,$m)||empty($_G['setting']['extcredits'][(int)($m[1]??0)]['title']))$credit=0;else $title=$_G['setting']['extcredits'][(int)$m[1]]['title'];
$operationLength=one('SELECT character_maximum_length n FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name=? AND column_name=?',[str_replace('`','',table('common_credit_log')),'operation']);$operation=(int)$operationLength['n']>=12?'lottery_draw':'lot';$recordId=0;$pdo->beginTransaction();try{
 exec_sql('INSERT INTO '.table('lottery_records').' (uid,dz_username,input_username,email,prize,ip,dateline) VALUES (?,?,?,?,?,?,?)',[$u['uid'],$u['username'],$u['username'],'',$selected['prize_name'],$_SERVER['REMOTE_ADDR'],time()]);$recordId=(int)$pdo->lastInsertId();
 if($credit){exec_sql('UPDATE '.table('common_member_count').' SET '.$field.'='.$field.'+? WHERE uid=?',[$credit,$u['uid']]);$amounts=array_fill(1,8,0);$amounts[(int)$m[1]]=$credit;exec_sql('INSERT INTO '.table('common_credit_log').' (uid,operation,relatedid,dateline,extcredits1,extcredits2,extcredits3,extcredits4,extcredits5,extcredits6,extcredits7,extcredits8) VALUES (?,?,0,?,?,?,?,?,?,?,?,?)',array_merge([$u['uid'],$operation,time()],array_values($amounts)));}
 $result=['prize'=>$selected['prize_name'],'remaining'=>max(0,$max-$count-1),'credit_value'=>$credit,'credit_title'=>$title,'credit_type'=>$credit?$field:null,'won'=>$selected['prize_name']!=='谢谢参与','record_id'=>$recordId,'operation'=>'lottery_draw'];exec_sql('INSERT INTO '.table('app_lottery_request').' VALUES (?,?,?,?)',[$u['uid'],$request,json_encode($result,JSON_UNESCAPED_UNICODE),time()]);$pdo->commit();respond($result);
}catch(Throwable $e){$pdo->rollBack();if($recordId)exec_sql('DELETE FROM '.table('lottery_records').' WHERE id=? AND uid=?',[$recordId,$u['uid']]);throw $e;}
